const rateBuckets=new Map();
function rateLimit(req,res,key,max,windowMs){const now=Date.now(),bucket=rateBuckets.get(key);if(!bucket||bucket.until<=now){rateBuckets.set(key,{count:1,until:now+windowMs});while(rateBuckets.size>10000)rateBuckets.delete(rateBuckets.keys().next().value);return false}bucket.count++;if(bucket.count<=max)return false;res.setHeader('Retry-After',String(Math.max(1,Math.ceil((bucket.until-now)/1000))));send(res,429,{error:'Demasiadas solicitudes. Espera un momento e inténtalo de nuevo.'});return true}
