function csrfAllowed(req){if(!['POST','PUT','PATCH','DELETE'].includes(req.method))return true;const fetchSite=(req.headers['sec-fetch-site']||'').toLowerCase();if(fetchSite&&fetchSite!=='same-origin')return false;const origin=req.headers.origin;if(!origin)return true;try{const parsed=new URL(origin),configured=process.env.PUBLIC_BASE_URL?new URL(process.env.PUBLIC_BASE_URL):null;if(configured&&parsed.origin===configured.origin)return true;const host=req.headers.host;if(!host)return false;const protocol=req.socket?.encrypted?'https:':'http:';return parsed.origin===`${protocol}//${host}`}catch{return false}}
