function validateImageData(data){if(typeof data!=='string'||data.length>3_000_000)throw Object.assign(new Error('La imagen debe ser PNG o JPG y pesar máximo 2 MB.'),{status:400});const match=data.match(/^data:image\/(png|jpeg);base64,([A-Za-z0-9+/]+={0,2})$/);if(!match)throw Object.assign(new Error('Formato inválido. Sube un archivo PNG o JPG.'),{status:400});const bytes=Buffer.from(match[2],'base64'),mime=match[1];if(bytes.length>2*1024*1024||bytes.length<32)throw Object.assign(new Error('La imagen debe pesar máximo 2 MB y ser válida.'),{status:400});let width=0,height=0;if(mime==='png'&&bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))){width=bytes.readUInt32BE(16);height=bytes.readUInt32BE(20)}else if(mime==='jpeg'&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255){let i=2;while(i+9<bytes.length){if(bytes[i]!==255){i++;continue}while(bytes[i]===255)i++;let marker=bytes[i++];if(marker===0xD9||marker===0xDA)break;if(i+2>bytes.length)break;let len=bytes.readUInt16BE(i);if(len<2||i+len>bytes.length)break;if([0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF].includes(marker)&&len>=7){height=bytes.readUInt16BE(i+3);width=bytes.readUInt16BE(i+5);break}i+=len}}if(!width||!height||width>6000||height>6000||width*height>25_000_000)throw Object.assign(new Error('La imagen está dañada o supera las dimensiones permitidas (6000 × 6000).'),{status:400});return {bytes,mime,extension:mime==='png'?'png':'jpg'}}
